Prepare Data


Code
df_monthly &lt;- readRDS(here("data/processed/monthly_values.rds"))

df_monthly_c &lt;- df_monthly |&gt;
  mutate(
    Date = make_date(year = Year, month = Month),
    Region = factor(
      Region,
      levels = c(
        "North",
        "Confluence",
        "SouthCentral",
        "Suisun Marsh",
        "Suisun Bay"
      )
    )
  ) |&gt;
  select(Date, Region, starts_with("bv_")) |&gt;
  pivot_longer(
    cols = starts_with("bv_"),
    names_to = "Algal_Group",
    values_to = "Biovolume",
    values_drop_na = TRUE
  ) |&gt;
  mutate(Algal_Group = str_remove(Algal_Group, "^bv_"))

Prepare Data


Code
df_seasonal &lt;- readRDS(here("data/processed/seasonal_values.rds"))

df_seasonal_c &lt;- df_seasonal |&gt;
  mutate(
    Region = factor(
      Region,
      levels = c(
        "North",
        "Confluence",
        "SouthCentral",
        "Suisun Marsh",
        "Suisun Bay"
      )
    )
  ) |&gt;
  select(YearAdj, Season, Region, starts_with("bv_")) |&gt;
  pivot_longer(
    cols = starts_with("bv_"),
    names_to = "Algal_Group",
    values_to = "Biovolume",
    values_drop_na = TRUE
  ) |&gt;
  mutate(Algal_Group = str_remove(Algal_Group, "^bv_"))
